const QT_RiyaPrimeLock: React.FC<{ onUnlock: () => void; onClose: () => void }> = ({ onUnlock, onClose }) => {
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [attempts, setAttempts] = useState(0);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (attempts >= 3) {
            setError("Too many attempts. Cooldown active (1h).");
            return;
        }
        if (password === RIYAPRIME_PASSWORD) {
            onUnlock();
        } else {
            setAttempts(p => p + 1);
            setError(`Incorrect Password. ${2 - attempts} attempts remaining.`);
        }
    };

    return (
        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-50 bg-black/90 backdrop-blur-xl flex items-center justify-center p-6">
            <div className="w-full max-w-md bg-[#0B1221] border border-[#ff006e]/30 rounded-2xl p-8 text-center relative overflow-hidden">
                <button onClick={onClose} className="absolute top-4 right-4 text-gray-500 hover:text-white"><XMarkIcon /></button>
                <div className="w-20 h-20 mx-auto bg-[#ff006e]/10 rounded-full flex items-center justify-center mb-6 border border-[#ff006e]/50">
                    <SparklesIcon className="w-10 h-10 text-[#ff006e]" />
                </div>
                <h2 className="text-2xl font-bold text-white mb-2">Riya Prime Access</h2>
                <p className="text-gray-400 text-sm mb-6">Enter secure key to unlock advanced voice & persona controls.</p>

                <form onSubmit={handleSubmit} className="space-y-4">
                    <input 
                        type="password" 
                        value={password} 
                        onChange={e => setPassword(e.target.value)} 
                        placeholder="Enter RIYAQR Key" 
                        className="w-full p-3 bg-black/50 border border-gray-700 rounded-xl text-center text-white focus:border-[#ff006e] outline-none tracking-widest"
                    />
                    {error && <p className="text-red-500 text-xs font-bold">{error}</p>}
                    <button type="submit" className="w-full py-3 bg-[#ff006e] hover:bg-[#d9005f] text-white font-bold rounded-xl transition-colors">UNLOCK SYSTEM</button>
                </form>
            </div>
        </motion.div>
    );
};

