const QT_VoiceStudio: React.FC<{ userProfile: UserProfile; onClose: () => void; onUpdate: (p: UserProfile) => void }> = ({ userProfile, onClose, onUpdate }) => {
    const qp = userProfile.quantumProfile!;
    const [config, setConfig] = useState({
        preset: qp.riyaVoicePreset,
        pitch: qp.voicePitch,
        speed: qp.voiceSpeed,
        emotion: qp.voiceEmotion || 50,
        breath: qp.voiceBreath || 30
    });
    const [isPlaying, setIsPlaying] = useState<string | null>(null);

    const handlePlay = async (voice: QuantumVoice) => {
        if (isPlaying) return;
        setIsPlaying(voice.id);
        const audioData = await generateSampleSpeech(voice.voiceId);
        if (audioData) {
            const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
            const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
            const source = ctx.createBufferSource();
            source.buffer = buffer;
            source.connect(ctx.destination);
            source.start();
            source.onended = () => setIsPlaying(null);
        } else {
            setIsPlaying(null);
        }
    };

    const handleSave = () => {
        onUpdate({
            ...userProfile,
            quantumProfile: {
                ...qp,
                riyaVoicePreset: config.preset,
                voicePitch: config.pitch,
                voiceSpeed: config.speed,
                voiceEmotion: config.emotion,
                voiceBreath: config.breath
            }
        });
        onClose();
    };

    return (
        <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-50 bg-[#0B1221] overflow-y-auto">
            <div className="p-6 max-w-2xl mx-auto space-y-8 pb-24">
                <div className="flex items-center justify-between">
                    <button onClick={onClose} className="p-2 bg-white/10 rounded-full hover:bg-white/20"><ArrowLeftIcon /></button>
                    <h2 className="text-xl font-bold tracking-widest text-[#2CB67D]">VOICE STUDIO</h2>
                    <div className="w-10"></div>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {RIYA_VOICE_VARIANTS.map(v => (
                        <div key={v.id} onClick={() => setConfig({...config, preset: v.id})} className={`p-4 rounded-xl border cursor-pointer transition-all ${config.preset === v.id ? 'bg-[#2CB67D]/10 border-[#2CB67D]' : 'bg-white/5 border-transparent hover:bg-white/10'}`}>
                            <div className="flex justify-between items-start mb-2">
                                <h3 className={`font-bold ${config.preset === v.id ? 'text-[#2CB67D]' : 'text-white'}`}>{v.name}</h3>
                                {config.preset === v.id && <div className="w-2 h-2 rounded-full bg-[#2CB67D] shadow-[0_0_10px_#2CB67D]"></div>}
                            </div>
                            <p className="text-xs text-gray-400 mb-4">{v.tagline}</p>
                            <button onClick={(e) => { e.stopPropagation(); handlePlay(v); }} className="flex items-center gap-2 text-xs font-bold bg-white/10 px-3 py-1.5 rounded-full hover:bg-white/20 transition-colors">
                                {isPlaying === v.id ? <SpeakerWaveIcon className="w-4 h-4 animate-pulse text-[#2CB67D]" /> : <SpeakerWaveIcon className="w-4 h-4" />}
                                Preview
                            </button>
                        </div>
                    ))}
                </div>
                 <div className="bg-white/5 rounded-2xl p-6 space-y-6 border border-white/5">
                    <h3 className="text-sm font-bold text-gray-500 uppercase tracking-wider">Fine Tuning</h3>
                    {[
                        { label: 'Pitch', key: 'pitch', min: -4, max: 4, step: 0.5, val: config.pitch },
                        { label: 'Speed', key: 'speed', min: 0.7, max: 1.4, step: 0.1, val: config.speed },
                    ].map(s => (
                        <div key={s.label}>
                            <div className="flex justify-between mb-2"><label className="text-sm font-bold text-gray-300">{s.label}</label><span className="text-xs font-mono text-[#7F5AF0]">{s.val}</span></div>
                            <input type="range" min={s.min} max={s.max} step={s.step} value={s.val} onChange={(e) => setConfig({...config, [s.key]: parseFloat(e.target.value)})} className="w-full accent-[#7F5AF0]" />
                        </div>
                    ))}
                </div>
            </div>
            <div className="fixed bottom-0 left-0 w-full p-6 bg-[#0B1221]/80 backdrop-blur-md border-t border-white/10 flex justify-center">
                <button onClick={handleSave} className={`${primaryBtn} w-full max-w-md`}>Save Voice Settings</button>
