    const [activeRoute, setActiveRoute] = useState<'none' | 'profile_full' | 'voice' | 'persona' | 'prime_lock' | 'prime_home' | 'settings'>('none');

    // UI State
    const [menuOpen, setMenuOpen] = useState(false);

    // Session State
    const [orbState, setOrbState] = useState<'idle' | 'listening' | 'processing' | 'speaking'>('idle');
    const isMicrophoneActive = useRef(false); // Gate for sending audio
    const [aiTranscript, setAiTranscript] = useState('');
    const [userTranscript, setUserTranscript] = useState('');
    const [warningMessage, setWarningMessage] = useState<string | null>(null);

    // Refs
    const aiRef = useRef<GoogleGenAI | null>(null);
    const sessionPromiseRef = useRef<Promise<LiveSession> | null>(null);
    const streamRef = useRef<MediaStream | null>(null);
    const inputAudioContextRef = useRef<AudioContext | null>(null);
    const outputAudioContextRef = useRef<AudioContext | null>(null);
    const audioQueueRef = useRef(new Set<AudioBufferSourceNode>());
    const nextAudioStartTimeRef = useRef(0);
    const analyserRef = useRef<AnalyserNode | null>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const animationFrameRef = useRef<number>();

    // Initial Onboarding Form Data
    const [formData, setFormData] = useState<Partial<QuantumProfile>>({
        displayName: userProfile.nickname || userProfile.name || '',
        fullName: userProfile.name || '',
        gender: 'Prefer not to say',
        languages: ['English'],
        interests: [],
        emotionalPersonality: [],
        emotionalSensitivity: 50,
        conversationDepth: 'adaptive',
        behaviorRestrictions: { avoidSensitive: false, strictMoral: true },
        riyaVoicePreset: 'warm',
        voicePitch: 0,
        voiceSpeed: 1.0,
        relationshipMode: 'Supportive AI Partner',
        purpose: [],
        usageFrequency: 'Daily',
        advancedPrefs: { memoryRetention: true, moodTracking: true, dailyGreetings: true },
        consentAudio: false,
    });
    const [generatedId, setGeneratedId] = useState('');

    // --- ONBOARDING LOGIC ---
    const updateForm = (key: keyof QuantumProfile, value: any) => setFormData(prev => ({ ...prev, [key]: value }));
    const handleNext = () => setStep(p => p + 1);
    const handleBack = () => setStep(p => p - 1);

    const StepIndicatorComp = () => <StepIndicator step={step} total={9} />;

    useEffect(() => {
        if (step === 8 && !generatedId) {
            const date = new Date().toISOString().slice(0, 10).replace(/-/g, '');
            const random = Math.floor(1000000 + Math.random() * 9000000);
            setGeneratedId(`QT-${date}-${random}`);
        }
    }, [step, generatedId]);

    const handleActivate = () => {
        const newProfile: QuantumProfile = {
            ...formData as QuantumProfile,
            id: generatedId,
            isActivated: true,
            activatedAt: new Date().toISOString(),
            strikes: 0,
            isSuspended: false,
            suspensionEndTime: null,
            isBanned: false,
            lastViolationDate: null,
            photoPrivacy: 'public',
            voiceConsent: true
        };
        onUpdateProfile({ ...userProfile, quantumProfile: newProfile });
        setStage('home');
    };

    // --- SESSION LOGIC ---
    useEffect(() => {
        if (stage !== 'home') return;

        const initSession = async () => {
            try {
                streamRef.current = await navigator.mediaDevices.getUserMedia({ audio: true });
                aiRef.current = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

                const qp = userProfile.quantumProfile!;
                const persona = PERSONA_LIBRARY.find(p => p.id === qp.activePersonaId);
                const voice = RIYA_VOICE_VARIANTS.find(v => v.id === qp.riyaVoicePreset);

                const systemInstruction = `You are Riya, a premium AI companion for ${qp.displayName}. Role: ${persona?.name || qp.relationshipMode}. Tone: ${persona?.behaviorStyle}. Speak naturally.`;

                sessionPromiseRef.current = aiRef.current.live.connect({
                    model: 'gemini-2.5-flash-native-audio-preview-09-2025',
                    callbacks: {
                        onopen: () => {
                            if (!streamRef.current) return;
                            inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
                            const ctx = inputAudioContextRef.current;
                            const source = ctx.createMediaStreamSource(streamRef.current);
                            const processor = ctx.createScriptProcessor(4096, 1, 1);

                            analyserRef.current = ctx.createAnalyser();
                            analyserRef.current.fftSize = 256;
                            source.connect(analyserRef.current);

                            processor.onaudioprocess = (e) => {
                                // GATED: Only send audio if microphone is explicitly active (Tap-to-Talk)
                                if (isMicrophoneActive.current) {
                                    const inputData = e.inputBuffer.getChannelData(0);
                                    sessionPromiseRef.current?.then(s => s.sendRealtimeInput({ media: createBlob(inputData) }));
                                }
                            };

                            analyserRef.current.connect(processor);
                            processor.connect(ctx.destination);
                        },
                        onmessage: async (msg: LiveServerMessage) => {
                            if (msg.serverContent?.inputTranscription) {
                                setUserTranscript(msg.serverContent.inputTranscription.text);
                            }
                            const audioData = msg.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
                            if (audioData) {
                                setOrbState('speaking');
                                setAiTranscript("Riya is speaking...");
                                if (!outputAudioContextRef.current) outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
                                const ctx = outputAudioContextRef.current;
                                const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
                                const source = ctx.createBufferSource();
                                source.buffer = buffer;
                                source.connect(ctx.destination);
                                const startTime = Math.max(ctx.currentTime, nextAudioStartTimeRef.current);
                                source.start(startTime);
                                nextAudioStartTimeRef.current = startTime + buffer.duration;
                                audioQueueRef.current.add(source);
                                source.onended = () => {
                                    audioQueueRef.current.delete(source);
                                    if (audioQueueRef.current.size === 0) {
                                        setOrbState('idle');
                                        setAiTranscript("");
                                    }
                                };
                            }
                        },
                        onclose: () => console.log('Session closed'),
                        onerror: (e) => console.error(e)
                    },
                    config: {
                        responseModalities: [Modality.AUDIO],
                        inputAudioTranscription: {},
                        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: voice?.voiceId || 'Kore' } } },
                        systemInstruction
                    }
                });
            } catch (e) {
                console.error("Failed to init session", e);
            }
        };
        initSession();
        return () => {
            sessionPromiseRef.current?.then(s => s.close());
            streamRef.current?.getTracks().forEach(t => t.stop());
            inputAudioContextRef.current?.close();
            outputAudioContextRef.current?.close();
        };
    }, [stage]);

    // --- ORB INTERACTIONS ---
    const handleOrbTap = () => {
        if (orbState === 'speaking') return; // Don't interrupt while speaking

        if (orbState === 'listening') {
            isMicrophoneActive.current = false;
            setOrbState('processing');
            setTimeout(() => { if(orbState === 'processing') setOrbState('idle'); }, 2000); 
        } else {
            isMicrophoneActive.current = true;
            setOrbState('listening');
        }
    };

    const handleOrbLongPressStart = () => {
        isMicrophoneActive.current = true;
        setOrbState('listening');
    };
    const handleOrbLongPressEnd = () => {
        isMicrophoneActive.current = false;
        setOrbState('processing');
        setTimeout(() => { if(orbState === 'processing') setOrbState('idle'); }, 2000); 
    };

    // --- CANVAS VISUALIZER ---
    useEffect(() => {
        if (stage !== 'home') return;
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        canvas.width = window.innerWidth;
        canvas.height = 400;
        const centerX = canvas.width / 2;
        const centerY = canvas.height / 2;
        let time = 0;

        const render = () => {
            time += 0.05;
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            let energy = 0;
            if (orbState === 'listening' && analyserRef.current) {
                const dataArray = new Uint8Array(analyserRef.current.frequencyBinCount);
                analyserRef.current.getByteFrequencyData(dataArray);
                energy = (dataArray.reduce((a, b) => a + b) / dataArray.length) / 255;
            } else if (orbState === 'speaking') {
                energy = (Math.sin(time * 0.5) + 1) * 0.3;
            }

            const baseRadius = 70;
            const pulse = energy * 50;
            const themeAccent = qp?.themeConfig?.accentColor || '#2CB67D';

            // Glow
            const gradient = ctx.createRadialGradient(centerX, centerY, baseRadius, centerX, centerY, baseRadius + 120 + pulse * 2);
            gradient.addColorStop(0, `${themeAccent}66`); // 40% opacity
            gradient.addColorStop(1, '#00000000');
            ctx.fillStyle = gradient;
            ctx.beginPath();
            ctx.arc(centerX, centerY, baseRadius + 120 + pulse, 0, Math.PI * 2);
            ctx.fill();

            // Orb Body
            ctx.fillStyle = orbState === 'listening' ? '#ef4444' : themeAccent; // Red when recording, else accent
            ctx.beginPath();
            ctx.arc(centerX, centerY, baseRadius + pulse * 0.6, 0, Math.PI * 2);
            ctx.fill();

            // Ripples
            if (orbState === 'listening' || orbState === 'speaking') {
                ctx.strokeStyle = themeAccent;
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.arc(centerX, centerY, baseRadius + 20 + (time * 10) % 60, 0, Math.PI * 2);
                ctx.stroke();
            }
            // Processing Ring
            if (orbState === 'processing') {
                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = 4;
                ctx.beginPath();
                ctx.arc(centerX, centerY, baseRadius + 20, time, time + 4);
                ctx.stroke();
            }

            animationFrameRef.current = requestAnimationFrame(render);
        };
        render();
        return () => { if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current); };
    }, [stage, orbState, qp?.themeConfig]);

    const renderOnboarding = () => (
        <div className="min-h-screen bg-[#0F172A] text-white flex flex-col font-sans overflow-y-auto">
            {step === 1 && (
                <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex-1 flex flex-col items-center justify-center p-8 text-center bg-[#0B1221]">
                    <div className="w-24 h-24 mb-6 rounded-full bg-gradient-to-tr from-[#7F5AF0] to-[#2CB67D] blur-xl opacity-60 absolute"></div>
                    <SparklesIcon className="w-16 h-16 text-[#2CB67D] mb-4 relative z-10" />
                    <h1 className="text-4xl font-bold mb-2 tracking-widest text-transparent bg-clip-text bg-gradient-to-r from-[#2CB67D] to-[#7F5AF0]">QUANTUM TEAP</h1>
                    <p className="text-gray-400 mb-8 font-mono text-sm">Identity Protocol v12.0</p>
                    <p className="text-gray-300 max-w-sm mb-12">Begin your AI-companion protocol. Create a deep, personalized identity for your AI interaction.</p>
                    <button onClick={handleNext} className={primaryBtn}>Start Initialization</button>
                </motion.div>
            )}

            {step > 1 && step < 10 && (
                <div className="flex-1 p-6 max-w-lg mx-auto w-full flex flex-col">
                    <div className="flex justify-between items-center mb-6">
                        <button onClick={handleBack} className="p-2 hover:bg-white/10 rounded-full"><ArrowLeftIcon /></button>
                        <h2 className="text-xs font-bold text-gray-500 uppercase tracking-widest">Setup Phase {step - 1}/8</h2>
                        <div className="w-8"></div>
                    </div>
                    <StepIndicatorComp />

                    <div className="flex-1 space-y-6">
                        {step === 2 && (
                            <motion.div initial={{ x: 20, opacity: 0 }} animate={{ x: 0, opacity: 1 }} className="space-y-4">
                                <h3 className="text-2xl font-bold mb-4">Identity Blueprint</h3>
                                <div><label className="text-xs text-[#2CB67D] font-bold uppercase mb-1 block">Display Name</label><input value={formData.displayName} onChange={e => updateForm('displayName', e.target.value)} className={inputStyle} placeholder="Your Nickname" /></div>
                                <div><label className="text-xs text-[#2CB67D] font-bold uppercase mb-1 block">Full Name</label><input value={formData.fullName} onChange={e => updateForm('fullName', e.target.value)} className={inputStyle} placeholder="Official Name" /></div>
                                <div><label className="text-xs text-[#2CB67D] font-bold uppercase mb-1 block">Bio & Interests</label><textarea value={formData.bio} onChange={e => updateForm('bio', e.target.value)} className={`${inputStyle} h-24`} placeholder="Tell Riya about yourself..." /></div>
                            </motion.div>
                        )}

                        {step === 3 && (
                            <motion.div initial={{ x: 20, opacity: 0 }} animate={{ x: 0, opacity: 1 }} className="space-y-6">
                                <h3 className="text-2xl font-bold">Emotional Matrix</h3>
                                <div>
                                    <label className="text-xs text-[#7F5AF0] font-bold uppercase mb-2 block">Personality Traits (Select up to 3)</label>
                                    <div className="flex flex-wrap gap-2">
                                        {PERSONALITY_TAGS.map(tag => (
                                            <button key={tag} onClick={() => {
                                                const current = formData.emotionalPersonality || [];
                                                updateForm('emotionalPersonality', current.includes(tag) ? current.filter(t => t !== tag) : [...current, tag].slice(0, 3));
                                            }} className={`px-3 py-2 rounded-lg text-sm font-bold border transition-all ${formData.emotionalPersonality?.includes(tag) ? 'bg-[#7F5AF0] border-[#7F5AF0] text-white' : 'bg-transparent border-gray-700 text-gray-400'}`}>
                                                {tag}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                                <div>
                                    <div className="flex justify-between mb-2"><label className="text-xs text-[#7F5AF0] font-bold uppercase">Emotional Sensitivity</label><span className="text-[#7F5AF0] text-xs">{formData.emotionalSensitivity}%</span></div>
                                    <input type="range" min="0" max="100" value={formData.emotionalSensitivity} onChange={e => updateForm('emotionalSensitivity', parseInt(e.target.value))} className="w-full accent-[#7F5AF0]" />
                                </div>
                            </motion.div>
                        )}

                        {step === 4 && (
                            <motion.div initial={{ x: 20, opacity: 0 }} animate={{ x: 0, opacity: 1 }} className="space-y-6">
                                <h3 className="text-2xl font-bold">Voice Lab</h3>
                                <div className="space-y-3">
                                    {RIYA_VOICE_VARIANTS.map(v => (
                                        <div key={v.id} onClick={() => updateForm('riyaVoicePreset', v.id)} className={`p-4 rounded-xl border cursor-pointer flex justify-between items-center transition-all ${formData.riyaVoicePreset === v.id ? 'bg-[#2CB67D]/10 border-[#2CB67D]' : 'bg-white/5 border-transparent'}`}>
                                            <div><h4 className={`font-bold ${formData.riyaVoicePreset === v.id ? 'text-[#2CB67D]' : 'text-white'}`}>{v.name}</h4><p className="text-xs text-gray-400">{v.tagline}</p></div>
                                            {formData.riyaVoicePreset === v.id && <div className="w-3 h-3 bg-[#2CB67D] rounded-full shadow-[0_0_10px_#2CB67D]"></div>}
                                        </div>
                                    ))}
                                </div>
                            </motion.div>
                        )}

                        {step === 5 && (
                            <motion.div initial={{ x: 20, opacity: 0 }} animate={{ x: 0, opacity: 1 }} className="space-y-6">
                                <h3 className="text-2xl font-bold">Relationship Mode</h3>
                                <div className="grid grid-cols-2 gap-3">
                                    {PERSONA_LIBRARY.filter(p => !p.isPremium).map(p => (
                                        <button key={p.id} onClick={() => updateForm('relationshipMode', p.name)} className={`p-4 rounded-xl border text-left transition-all ${formData.relationshipMode === p.name ? 'bg-white/10 border-white text-white' : 'bg-transparent border-gray-700 text-gray-400'}`}>
                                            <div className="font-bold text-sm mb-1">{p.name}</div>
                                            <div className="text-[10px] opacity-70">{p.behaviorStyle}</div>
                                        </button>
                                    ))}
                                </div>
                                <div className="p-3 bg-yellow-900/30 border border-yellow-700/50 rounded-lg text-xs text-yellow-200">
                                    ⚠️ Note: Romantic responses are disabled for users under 18.
                                </div>
                            </motion.div>
                        )}

                        {step === 6 && (
                            <motion.div initial={{ x: 20, opacity: 0 }} animate={{ x: 0, opacity: 1 }} className="space-y-6">
                                <h3 className="text-2xl font-bold">Usage Purpose</h3>
                                <div className="flex flex-wrap gap-2">
                                    {PURPOSE_OPTIONS.map(p => (
                                        <button key={p} onClick={() => {
                                            const current = formData.purpose || [];
                                            updateForm('purpose', current.includes(p) ? current.filter(x => x !== p) : [...current, p]);
                                        }} className={`px-3 py-2 rounded-lg text-xs font-bold border transition-all ${formData.purpose?.includes(p) ? 'bg-[#ff006e] border-[#ff006e] text-white' : 'bg-transparent border-gray-700 text-gray-400'}`}>
                                            {p}
                                        </button>
                                    ))}
                                </div>
                            </motion.div>
                        )}

                        {step === 7 && (
                            <motion.div initial={{ x: 20, opacity: 0 }} animate={{ x: 0, opacity: 1 }} className="space-y-6">
                                <h3 className="text-2xl font-bold text-red-400">Safety & T&C</h3>
                                <div className="bg-white/5 p-4 rounded-xl text-sm text-gray-300 h-64 overflow-y-auto whitespace-pre-wrap border border-white/10 font-mono">
                                    {LEGAL_DISCLAIMER}
                                </div>
                                <div className="flex items-start gap-3">
                                    <input type="checkbox" className="mt-1 w-5 h-5 accent-[#2CB67D]" id="accept" />
                                    <label htmlFor="accept" className="text-sm text-gray-400">I accept these terms & understand this is an AI.</label>
                                </div>
                            </motion.div>
                        )}

                        {step === 8 && (
                            <motion.div initial={{ x: 20, opacity: 0 }} animate={{ x: 0, opacity: 1 }} className="text-center space-y-8 pt-10">
                                <ShieldCheckIcon className="w-20 h-20 text-[#2CB67D] mx-auto" />
                                <h3 className="text-2xl font-bold">Identity Generated</h3>
                                <div className="bg-white/10 p-6 rounded-2xl border border-white/20 inline-block">
                                    <p className="text-xs text-gray-400 uppercase tracking-widest mb-2">QUANTUM ID</p>
                                    <p className="text-3xl font-mono font-bold text-[#2CB67D] tracking-wider">{generatedId || 'GENERATING...'}</p>
                                </div>
                                <p className="text-gray-400 max-w-xs mx-auto">Your profile is ready. Riya is initialized and waiting for connection.</p>
                            </motion.div>
                        )}

                        {step === 9 && (
                             <motion.div initial={{ scale: 0.8, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="flex-1 flex flex-col items-center justify-center text-center">
                                <div className="relative mb-8">
                                    <div className="absolute inset-0 bg-[#2CB67D] blur-3xl opacity-20 rounded-full animate-pulse"></div>
                                    <SparklesIcon className="w-32 h-32 text-[#2CB67D] relative z-10" />
                                </div>
                                <h2 className="text-4xl font-bold text-white mb-4">ACTIVATED</h2>
                                <p className="text-xl text-gray-300 mb-8">Welcome home, {formData.displayName}.</p>
                                <button onClick={handleActivate} className={primaryBtn}>Enter Quantum Home</button>
                            </motion.div>
                        )}
                    </div>

                    {step < 9 && (
                        <div className="pt-6 border-t border-white/10 mt-auto">
                            <button onClick={step === 8 ? () => setStep(9) : handleNext} className={primaryBtn + " w-full"}>
                                {step === 8 ? "Finalize Activation" : "Continue"}
                            </button>
                        </div>
                    )}
                </div>
            )}
        </div>
    );

    if (stage === 'onboarding') return renderOnboarding();

    const theme = qp?.themeConfig || THEME_PRESETS[0];

    return (
        <div className={`relative w-full h-full ${theme.backgroundGradient} text-white font-sans overflow-hidden flex flex-col`}>
            {/* Top Menu Bar */}
            <div className="flex justify-between items-center p-4 bg-white/5 backdrop-blur-md border-b border-white/5 z-30">
                <h1 className="text-lg font-bold tracking-widest text-[#2CB67D] flex items-center gap-2">
                    <SparklesIcon className="w-5 h-5" />
                    QUANTUM TEAP
                </h1>
                <div className="flex items-center gap-4 text-xs font-bold text-gray-300">
                    <button onClick={() => setActiveRoute('profile_full')} className="hover:text-white transition-colors">GU</button>
                    <button onClick={() => setActiveRoute('voice')} className="hover:text-white transition-colors">VOICE</button>
                    <button onClick={() => setActiveRoute('persona')} className="hover:text-white transition-colors">PERSONA</button>
                    <button onClick={() => setActiveRoute('prime_lock')} className="hover:text-white transition-colors">PRIME</button>
                </div>
            </div>

            {/* Main Content */}
            <div className="flex-1 relative flex flex-col items-center justify-center p-4">
                {/* Supportive Chip */}
                <div className="absolute top-4 left-4 z-20">
                    <button className="flex items-center gap-2 px-3 py-1.5 bg-white/5 border border-white/10 rounded-full hover:bg-white/10 transition-all">
                        <div className="w-2 h-2 rounded-full bg-green-400 animate-pulse"></div>
                        <span className="text-[10px] font-bold tracking-wider text-gray-300">SUPPORTIVE AI PARTNER</span>
                    </button>
                </div>

                {/* Orb Visualizer */}
                <div className="relative w-full max-w-lg h-[400px] flex items-center justify-center">
                    <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />
                    <button 
                        onMouseDown={handleOrbLongPressStart} 
                        onMouseUp={handleOrbLongPressEnd} 
                        onTouchStart={handleOrbLongPressStart} 
                        onTouchEnd={handleOrbLongPressEnd}
                        onClick={handleOrbTap}
                        className="w-48 h-48 rounded-full z-10 opacity-0 cursor-pointer"
                    >
                        Interaction Layer
                    </button>
                    <div className="absolute bottom-10 pointer-events-none text-center">
                        <p className="text-sm font-mono text-gray-400 tracking-widest mb-1">
                            {orbState === 'idle' ? 'TAP TO CONNECT' : (orbState === 'listening' ? 'LISTENING...' : (orbState === 'speaking' ? 'SPEAKING' : 'PROCESSING'))}
                        </p>
                        {(aiTranscript || userTranscript) && (
                            <p className="text-lg font-bold text-white max-w-xs mx-auto animate-fade-in text-center line-clamp-2">
                                {aiTranscript || `"${userTranscript}"`}
                            </p>
                        )}
                    </div>
                </div>
            </div>

            {/* Bottom Nav */}
            <div className="p-4 bg-[#0B1221]/80 backdrop-blur-md border-t border-white/5 flex justify-around z-30">
                <button onClick={() => setActiveRoute('none')} className="flex flex-col items-center gap-1 text-[#2CB67D]">
                    <div className="w-6 h-6"><MenuIcon /></div>
                    <span className="text-[10px] font-bold">HOME</span>
                </button>
                <button onClick={() => setActiveRoute('persona')} className="flex flex-col items-center gap-1 text-gray-500 hover:text-white transition-colors">
                    <div className="w-6 h-6"><UserIcon /></div>
                    <span className="text-[10px] font-bold">PERSONA</span>
                </button>
                <button onClick={() => setActiveRoute('voice')} className="flex flex-col items-center gap-1 text-gray-500 hover:text-white transition-colors">
                    <div className="w-6 h-6"><SpeakerWaveIcon /></div>
                    <span className="text-[10px] font-bold">VOICE</span>
                </button>
                <button onClick={() => onClose()} className="flex flex-col items-center gap-1 text-gray-500 hover:text-white transition-colors">
                    <div className="w-6 h-6"><XMarkIcon /></div>
                    <span className="text-[10px] font-bold">EXIT</span>
                </button>
            </div>

            {/* Overlays */}
            <AnimatePresence>
                {activeRoute === 'profile_full' && <QT_ProfileFull userProfile={userProfile} onUpdate={onUpdateProfile} onClose={() => setActiveRoute('none')} />}
                {activeRoute === 'persona' && <QT_PersonaCenter userProfile={userProfile} onUpdate={onUpdateProfile} onClose={() => setActiveRoute('none')} />}
                {activeRoute === 'voice' && <QT_VoiceStudio userProfile={userProfile} onUpdate={onUpdateProfile} onClose={() => setActiveRoute('none')} />}
                {activeRoute === 'prime_lock' && <QT_RiyaPrimeLock onUnlock={() => setActiveRoute('prime_home')} onClose={() => setActiveRoute('none')} />}
