const QT_VoiceStudio: React.FC<{ userProfile: UserProfile; onClose: () => void; onUpdate: (p: UserProfile) => void }> = ({ userProfile, onClose, onUpdate }) => {
    const qp = userProfile.quantumProfile!;
    const [config, setConfig] = useState({
        preset: qp.riyaVoicePreset,
        pitch: qp.voicePitch,
        speed: qp.voiceSpeed,
        emotion: qp.voiceEmotion || 50,
        breath: qp.voiceBreath || 30
    });
    const [isPlaying, setIsPlaying] = useState<string | null>(null);

    const handlePlay = async (voice: QuantumVoice) => {
        if (isPlaying) return;
        setIsPlaying(voice.id);
        const audioData = await generateSampleSpeech(voice.voiceId);
        if (audioData) {
            const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
            const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
            const source = ctx.createBufferSource();
            source.buffer = buffer;
            source.connect(ctx.destination);
            source.start();
            source.onended = () => setIsPlaying(null);
        } else {
            setIsPlaying(null);
        }
    };

    const handleSave = () => {
        onUpdate({
            ...userProfile,
            quantumProfile: {
                ...qp,
                riyaVoicePreset: config.preset,
                voicePitch: config.pitch,
